def frontier(M, shifts=np.arange(-6,6.01,0.1)):
    out=[]
    for s in shifts:
        accs = np.array([group_stats(M[r]+s)[0] for r in range(M.shape[0])]).mean(0)
        out.append((s, accs.min(), (accs*GW).sum(), *accs))
    return np.array(out)
def frontier_summary(M, name):
    Fr = frontier(M)
    txt = '%-30s' % name
    for lvl in [95.0, 95.5, 96.0, 96.5, 97.0]:
        ok = Fr[Fr[:,2]>=lvl]
        if len(ok)==0: txt += ' | >=%.1f: --' % lvl; continue
        j = np.argmax(ok[:,1]); txt += ' | m>=%.1f: w %.1f' % (lvl, ok[j,1])
    j = np.argmax(Fr[:,1]); txt += ' || max worst %.1f at shift %.1f (mean %.2f; LL %.1f LW %.1f WL %.1f WW %.1f)' % (Fr[j,1], Fr[j,0], Fr[j,2], *Fr[j,3:])
    return txt
